})

function escapeHTMLchar(str) {
    return str.replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

//keep the code label for other specified
var others = document.querySelectorAll(".cf-checkbox-answer__other.cf-text-box, .cf-text-box.cf-radio-answer__other, .cf-grid-3d-desktop__answer-other-input.cf-text-box, .cf-text-box, .cf-desktop-grid__answer-other");
for (let i = 0; i < others.length; i++) {
    var other = others[i];
    var parent = other.parentNode
    /*var text = other.placeholder + " <font color='#0000FF'>(SPECIFY)</font> ";*/
    var text = other.placeholder;
    other.placeholder = "";
    var newElement = document.createElement("span");
    newElement.innerHTML = text;
    // set max length to all other textbox
    other.setAttribute('maxlength', 4000);
    parent.insertBefore(newElement, other);
}
setTimeout(function () {
    $('.cf-checkbox-answer__other.cf-text-box, .cf-radio-answer__other.cf-text-box, .cf-grid-3d-desktop__answer-other-input.cf-text-box, .cf-text-box, .cf-desktop-grid__answer-other.cf-text-box').attr('placeholder', '');
}, 1)
// set max length to all text questions
// copy this into a specific question's javascript and set a different max (if needed)
document.querySelectorAll("textarea").forEach(function (el) {
    el.maxLength = 4000;
});

/*Save button*/
function validateData(){
    var result = Confirmit.page.validate();
    var errors = result.questionValidationResults.length;
    if(errors == 0){
        saveData();
    }
}

function clearData() {
    var responses = Confirmit.page.questions;
    for (var i = 0; i < responses.length; i++) {
        var question = responses[i];
        if(Object.keys(question.formValues).length > 0){
            question.clearValues();
        }
    }
}

function saveData() {

    var url = document.URL;
    var params = Confirmit.page.serverVariables._fields;

    var responses = Confirmit.page.formValues;
    for (var i = 0; i < responses.length; i++) {
        var name = responses[i]["name"];
        var value = responses[i]["value"];
        params[name] = value;
    }

    var xhr = new XMLHttpRequest();
    xhr.open("POST", url, true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4 && xhr.status === 200) {
            document.getElementById("save-btn").innerText = "Saved!";
            setTimeout(function () {
                document.getElementById("save-btn").innerText = "Save and close";
            }, 2000);
        }
    };
    var queryString = new URLSearchParams(params).toString();
    xhr.send(queryString);
}

function reverse_grid_s_order(parent_elem,child_elem,fixitemCount)
{
    let remaining 
    if (fixitemCount > 0) {
    // Separate last two element
     remaining = child_elem.slice(0, fixitemCount*-1); 
    }
    else
    {
     remaining = child_elem
    }
    // Reverse and re-append only the remaining elements
    remaining.toArray().reverse().forEach(th => parent_elem.append(th));
     
    if (fixitemCount>0){
        let lastTwo = child_elem.slice(fixitemCount * -1);
        // Re-append last two elements to preserve their original order
        lastTwo.each((_, th) => parent_elem.append(th));
    }

}
 
function categorical_hideDKREF() {
    if (IntMode == 'CAWI') {
        if ($('.cf-searchable-question__other-answers').length > 0) {
            var exclusivecodesLength = $('.exclusivecodes').length

            $('.cf-page__question-list .cf-question').each(function () {
                if ($('.cf-radio--selected').length == 0 && $('.cf-checkbox--selected').length == 0 && $('.cf-error-list__item').length == 0 && exclusivecodesLength > 0) {
                    $(this).find('.cf-searchable-question__other-answers .cf-list__item').has('.exclusivecodes').hide()
                }
            })
        }
        else {
            var exclusivecodesLength = $('.exclusivecodes').length

            if ($('.cf-radio--selected').length == 0 && $('.cf-checkbox--selected').length == 0 && $('.cf-error-list__item').length == 0 && exclusivecodesLength > 0) {
                $(".cf-list .cf-list__item").slice(-1 * exclusivecodesLength).hide()
            }
        }

        $('.cf-navigation').on('click', function () {
            if ($('.cf-error-list__item').length > 0) {
                $(".cf-list .cf-list__item").show()

                $('.cf-error-list__item').each(function () {
                    if ($(this).text().trim().includes('Please select an answer')) {
                        $(this).text('You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?');
                    }
                });
            }
        })
    }
}

