}

function autocomplete(inp, arr, codes, qId, MinChar) {
    /*the autocomplete function takes two arguments,
    the text field element and an array of possible autocompleted values:*/
    var currentFocus;
    /*execute a function when someone writes in the text field:*/
    inp.addEventListener("input", function (e) {
        var a, b, i, val = this.value;
        /*close any already open lists of autocompleted values*/
        closeAllLists();
        if (!val||val.length<MinChar) { return false; }
        currentFocus = -1;
        /*create a DIV element that will contain the items (values):*/
        a = document.createElement("DIV");
        a.setAttribute("id", this.id + "autocomplete-list");
        a.setAttribute("class", "autocomplete-items");
        /*append the DIV element as a child of the autocomplete container:*/
        this.parentNode.appendChild(a);
        /*for each item in the array...*/
        for (i = 0; i < arr.length; i++) {
            /*Option  1 - check if the item starts with the same letters as the text field value:
            if (arr[i].substr(0, val.length).toUpperCase() == val.toUpperCase()) {*/

            /*Option  2 - check substring match */
            if (arr[i].toUpperCase().indexOf(val.toUpperCase()) > -1 ) {


                /*create a DIV element for each matching element:*/
                b = document.createElement("DIV");
                /*make the matching letters bold:*/
                b.innerHTML = "<strong>" + arr[i].substr(0, val.length) + "</strong>";
                b.innerHTML += arr[i].substr(val.length);
                /*insert a input field that will hold the current array item's value:*/
                b.innerHTML += "<input type='hidden' value='" + arr[i] + "'>";
                /*execute a function when someone clicks on the item value (DIV element):*/
                b.addEventListener("click", function (e) {
                    /*insert the value for the autocomplete text field:*/
                    inp.value = this.getElementsByTagName("input")[0].value;
                    /*close the list of autocompleted values,
                    (or any other open lists of autocompleted values:*/
                    closeAllLists();
                    setQuestionValue(qId,inp.value);
                });
                a.appendChild(b);
            }
        }
    });
    /*execute a function presses a key on the keyboard:*/
    inp.addEventListener("keydown", function (e) {
        var x = document.getElementById(this.id + "autocomplete-list");
        if (x) x = x.getElementsByTagName("div");
        if (e.keyCode == 40) {
            /*If the arrow DOWN key is pressed,
            increase the currentFocus variable:*/
            currentFocus++;
            /*and and make the current item more visible:*/
            addActive(x);
        } else if (e.keyCode == 38) { //up
            /*If the arrow UP key is pressed,
            decrease the currentFocus variable:*/
            currentFocus--;
            /*and and make the current item more visible:*/
            addActive(x);
        } else if (e.keyCode == 13) {
            /*If the ENTER key is pressed, prevent the form from being submitted,*/
            e.preventDefault();
            if (currentFocus > -1) {
                /*and simulate a click on the "active" item:*/
                if (x) {
                    x[currentFocus].click();
                   
                }
            }
        }
    });
    
    function setQuestionValue(qId, val) {

        Confirmit.page.getQuestion(qId).setValue(val);
    }

    function addActive(x) {
        /*a function to classify an item as "active":*/
        if (!x) return false;
        /*start by removing the "active" class on all items:*/
        removeActive(x);
        if (currentFocus >= x.length) currentFocus = 0;
        if (currentFocus < 0) currentFocus = (x.length - 1);
        /*add class "autocomplete-active":*/
        x[currentFocus].classList.add("autocomplete-active");
    }
    function removeActive(x) {
        /*a function to remove the "active" class from all autocomplete items:*/
        for (var i = 0; i < x.length; i++) {
            x[i].classList.remove("autocomplete-active");
        }
    }
    function closeAllLists(elmnt) {
        /*close all autocomplete lists in the document,
        except the one passed as an argument:*/
        var x = document.getElementsByClassName("autocomplete-items");
        for (var i = 0; i < x.length; i++) {
            if (elmnt != x[i] && elmnt != inp) {
                x[i].parentNode.removeChild(x[i]);
            }
        }
    }
    /*execute a function when someone clicks in the document:*/
    document.addEventListener("click", function (e) {
        closeAllLists(e.target);
    });
}
 

//disable copy and paste for open-end questions
function disableCopyPasteForElement(el) { 
  if (!el.dataset.copyPasteDisabled) { 
    el.addEventListener('copy', (e) => e.preventDefault()); 
    el.addEventListener('cut', (e) => e.preventDefault()); 
    el.addEventListener('paste', (e) => e.preventDefault()); 
    el.dataset.copyPasteDisabled = 'true'; // Prevents double binding 
  } 
} 

document.querySelectorAll('input, textarea').forEach(disableCopyPasteForElement); 
 

// We have to generate a key for the timestamp submission for each page. We do this by combining the ids of the 
// individual questions.
function getPageId() {
    let questions;
    try {
        questions = window.Confirmit.page.questions;
    } catch(e) {
        //console.debug("window.Confirmit.page.questions object could not be found.");
        return "timestamp_error_default";
    }
   
    const questionNames = questions.map(q => q?.id)
    for (let name of questionNames) {
        if (!name || String(name).length < 1) {
            //console.debug("missing question id");
            return "timestamp_error_default";
        }
    }

    return questionNames.join("-");
}
 
 // time stamp without idle time
document.addEventListener("DOMContentLoaded", () => {
    createIdleAwareTimer({
        idleThresholdSeconds: 60,
        tickIntervalMs: 1000,
        onActiveTick: createActiveTimeRecorder("pageTime")
    }).start();
});

function createActiveTimeRecorder(variableName) {
    let activeSeconds = 0;
    const startTime = (new Date()).toISOString();
    const pageId = getPageId();

    return () => {
        activeSeconds += 1;
        syncServerTime(variableName, JSON.stringify({
            pageId,
            startTime,
            activeSeconds
        }));
    };
}

function syncServerTime(variableName, newValue) {
    // This two step is required because once a serverVariable is created via `.add()`, 
    // subsequent calls to `.add()` will silently do nothing (value will not get updated)
    Confirmit.page.serverVariables.add(variableName, newValue);
    Confirmit.page.serverVariables.edit(variableName, newValue);
    console.log("New server time is: " + Confirmit.page.serverVariables.get(variableName));
}

function createIdleAwareTimer({ idleThresholdSeconds, tickIntervalMs, onActiveTick }) {
    let idleSeconds = 0;
    let intervalId = null;
    let eventsAttached = false;

    const resetIdle = () => {
        idleSeconds = 0;
    };

    const stop = () => {
        if (intervalId !== null) {
            clearInterval(intervalId);
            intervalId = null;
        }
    };

    const tick = () => {
        if (idleSeconds < idleThresholdSeconds) {
            onActiveTick();
        }
        idleSeconds += 1;
    };

    const start = () => {
        attachEvents();
        stop();
        intervalId = window.setInterval(tick, tickIntervalMs);
    };

    const attachEvents = () => {
        if (eventsAttached) return;
        eventsAttached = true;

        document.addEventListener("click", resetIdle);
        document.addEventListener("mousemove", resetIdle);
        document.addEventListener("keydown", resetIdle);

        window.addEventListener("blur", stop);
        window.addEventListener("focus", start);
    };

    return { start, stop };
}

