function hideDKREF_textlist() {

    $("[id$='_dk']").hide();
    $("[id$='_ref']").hide();

    setInterval(function () {

        if ($(".cf-error-list__item").length > 0) {

            $("[id$='_dk']").show();
            $("[id$='_ref']").show();

            $('.cf-error-list__item').each(function () {

                var txt = $(this).text().trim();

                if (
                    txt.includes('Please provide an answer.') ||
                    txt.includes('Please select at least 1 answer.')
                ) {

                    $(this).text(
                        'You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?'
                    );
                }
            });
        }

    }, 10);
}

