Multi.StartupScript:
$(document).ready(function () {

    // Rows
    var row2 = $("#Q2c_2");
    var row3 = $("#Q2c_3");

    // Inputs
    var input1 = $("#Q2c_1_input");
    var input2 = $("#Q2c_2_input");
    var input3 = $("#Q2c_3_input");

    // Set 60-character limits
    input1.attr("maxlength", "60");
    input2.attr("maxlength", "60");
    input3.attr("maxlength", "60");

    // Add character counters
    input1.after('<div id="Q2c_1_count" style="font-size:12px;color:#666;margin-top:3px;">' + input1.val().length + ' / 60</div>');
    input2.after('<div id="Q2c_2_count" style="font-size:12px;color:#666;margin-top:3px;">' + input2.val().length + ' / 60</div>');
    input3.after('<div id="Q2c_3_count" style="font-size:12px;color:#666;margin-top:3px;">' + input3.val().length + ' / 60</div>');

    // Button to reveal response 2
    var btn2 = $('<button type="button" id="showRow2">Add another issue</button>');
    btn2.prop("disabled", input1.val().trim().length < 3);
    btn2.css("margin-left", "15px");

    input1.closest(".cf-affix-input-decorator").after(btn2);

    // Button to reveal response 3
    var btn3 = $('<button type="button" id="showRow3">Add another issue</button>');
    btn3.prop("disabled", input2.val().trim().length < 3);
    btn3.css("margin-left", "15px");

    input2.closest(".cf-affix-input-decorator").after(btn3);

    // Hide rows ONLY if empty
    if (input2.val().trim() === "") {
        row2.hide();
    }

    if (input3.val().trim() === "") {
        row3.hide();
    }

    // If data already exists, keep row visible and hide button
    if (input2.val().trim() !== "") {
        row2.show();
        btn2.hide();
    }

    if (input3.val().trim() !== "") {
        row3.show();
        btn3.hide();
    }

    // Update counter and enable Button 1
    input1.on("input", function () {

        $("#Q2c_1_count").text($(this).val().length + " / 60");

        btn2.prop(
            "disabled",
            $(this).val().trim().length < 3
        );
    });

    // Update counter and enable Button 2
    input2.on("input", function () {

        $("#Q2c_2_count").text($(this).val().length + " / 60");

        btn3.prop(
            "disabled",
            $(this).val().trim().length < 3
        );
    });

    // Update counter for Response 3
    input3.on("input", function () {

        $("#Q2c_3_count").text($(this).val().length + " / 60");

    });

    // Show Response 2
    btn2.on("click", function () {
        row2.show();
        btn2.hide();
    });

    // Show Response 3
    btn3.on("click", function () {
        row3.show();
        btn3.hide();
    });

});


