$(function () {

    var promptWidth = 350;
    var responseWidth = 115;

    $(".cf-table-layout").each(function () {

        var $table = $(this);

        // Remove the colgroup added by the previous script
        $table.children("colgroup.custom-grid-widths").remove();

        // Allow the table to grow wider than the available page width
        $table.css({
            "table-layout": "auto",
            "width": "max-content",
            "min-width": "100%"
        });

        // Fix the prompt column width
        $table.find(
            "tbody .cf-table-layout__cell--row-head"
        ).css({
            "width": promptWidth + "px",
            "min-width": promptWidth + "px",
            "max-width": promptWidth + "px",
            "box-sizing": "border-box"
        });

        // Keep the prompt's inner container within that column
        $table.find(
            ".cf-table-layout-cell--row-head"
        ).css({
            "width": promptWidth + "px",
            "min-width": promptWidth + "px",
            "max-width": promptWidth + "px",
            "box-sizing": "border-box"
        });

        // Widen every response heading
        $table.find(
            "thead .cf-table-layout__cell--column-head"
        ).css({
            "width": responseWidth + "px",
            "min-width": responseWidth + "px",
            "box-sizing": "border-box"
        });

        // Widen every response cell
        $table.find(
            "tbody .cf-desktop-grid__answer > td.cf-table-layout__cell"
        ).css({
            "width": responseWidth + "px",
            "min-width": responseWidth + "px",
            "box-sizing": "border-box"
        });

        // Ensure prompt text wraps normally
        $table.find(".cf-desktop-grid__answer-text").css({
            "white-space": "normal",
            "overflow-wrap": "break-word"
        });

        // Stop scale labels from forcing the columns narrower
        $table.find(".cf-desktop-grid__scale-text").css({
            "white-space": "normal",
            "overflow-wrap": "break-word"
        });

        // Allow horizontal scrolling if the complete grid is wider than the page
        $table.parent().css({
            "overflow-x": "auto",
            "max-width": "100%"
        });

    });

});

Script.ScriptCode:
/*
CORE 10 STATEMENTS (A-J) ALWAYS SHOW
a	A foreign military attack on Australia	**
b	A foreign country interfering in Australia’s politics, government, economy or society	
c	Disruption to critical supplies due to a crisis overseas	**
d	The deliberate spread of false information to mislead the Australian public and harm their interests	**
e	An attack on Australia’s critical infrastructure like transport, energy or communications	**
f	The use of artificial intelligence to attack Australian people or businesses	
g	A severe economic crisis	**
h	Major natural disasters on a scale not seen here before **
i	A terrorist attack in Australia	
j	Violent extremism targeting a part of the Australian community	**

ROTATE SELECTION OF 3 ITEMS TO SHOW
k	Australia becoming involved in a military conflict with another country	
l	A world in which no rules stop the strongest countries doing what they want	
m	A major cyberattack targeting Australian people or businesses	**
n	An introduced disease that poses a widespread threat to Australia’s animals and plants	
o	A global health pandemic	**
p	The impacts of climate change	**
q	Violent unrest between different groups of Australians	
r	Serious and organised crime (homegrown or international) targeting Australian people or businesses	
s	Australia being unable to effectively secure and manage its borders	

    ' ** ' INDICATES THE ‘HOUSEHOLD ACTIONABLE’ ITEMS REQUIRED FOR Q6d.
*/
function q6Mask () {
  const core = set('a','b','c','d','e','f','g','h','i','j');
  //const part = set('k','l','m','n','o','p','q','r','s');

  if (!f('Q6part').toBoolean() || (f('Q6part').size() < 3)) {
    if(IsInProductionMode()) {
      for (var i = 1; i <= 3; i++) {
        var qset = a('Q6part_' + i.toString()).diff(getMultiCodes("Q6part"));
        var quotaCode = GetLeastFilledQuotaCodes('Quota_Q6part_' + i.toString(), 1, qset.members());
        f('Q6part_' + i.toString()).set(quotaCode[0]);
        f('Q6part').item(quotaCode[0]).set('1');
      }
    } else {
      const part = ['k','l','m','n','o','p','q','r','s'];

      for (var i = 1; i <= 3; i++) {
        var randomIndex = Math.floor(Math.random() * part.length);
        var randomItem = part[randomIndex];

        f('Q6part_' + i.toString()).set(randomItem);
        f('Q6part').item(randomItem).set('1');

        part.splice(randomIndex, 1);
      }
    }
  }

  return core.union(getMultiCodes('Q6part'));
}

function hhActionable () {
  return set('a','c','d','e','g','h','j','m','o','p');
}

function getMultiCodes(qn) {
  qset = new set();
  f(qn).domainValues().forEach(function (item){
    if (f(qn).item(item) == '1') qset.add(item);
  });
  return qset;
}

