/*
$(function () {
  window.setTimeout(function () {

    var orderStr = '^f("Q6ai_ORDER")^';

    // If Q6ai_ORDER has no response, use Q6_ORDER instead
    if (
      !orderStr ||
      orderStr.trim() === '' ||
      orderStr.toUpperCase().indexOf('NO RESPONSE') > -1
    ) {
      orderStr = '^f("Q6_ORDER")^';
    }

    // If neither variable has a usable value, do nothing
    if (
      !orderStr ||
      orderStr.trim() === '' ||
      orderStr.toUpperCase().indexOf('NO RESPONSE') > -1
    ) {
      return;
    }

    var order = orderStr.split(',');

    // Find the response list
    var list = document.querySelector('.cf-list');

    if (!list) {
      return;
    }

    var items = list.querySelectorAll('.cf-list__item');
    var responseMap = {};
    var i;
    var item;
    var answer;
    var idParts;
    var code;

    // Build response code -> list item map
    for (i = 0; i < items.length; i++) {

      item = items[i];

      answer = item.querySelector(
        '.cf-checkbox-answer[id], .cf-radio-answer[id]'
      );

      if (!answer || !answer.id) {
        continue;
      }

      // Q7c_a  -> a
      // Q7c_n  -> n
      // Q7c_97 -> 97
      idParts = answer.id.split('_');
      code = idParts[idParts.length - 1];

      responseMap[code] = item;
    }

    // Reorder the normal responses
    for (i = 0; i < order.length; i++) {

      code = order[i].trim();

      // Never allow fixed responses to be repositioned here
      if (
        code !== '97' &&
        code !== '98' &&
        code !== '99' &&
        responseMap[code]
      ) {
        list.appendChild(responseMap[code]);
      }
    }

    // Always put fixed responses at the bottom
    if (responseMap['97']) {
      list.appendChild(responseMap['97']);
    }

    if (responseMap['98']) {
      list.appendChild(responseMap['98']);
    }

    if (responseMap['99']) {
      list.appendChild(responseMap['99']);
    }

  }, 100);
});

*/

