Script.ScriptCode:
// Only generate the order once
if (!f("Q18_POS1").toBoolean()) {

    var order = [
        "1", // Q18a
        "2", // Q18b
        "3", // Q18c
        "4", // Q18d
        "5", // Q18e
        "6", // Q18f
        "7", // Q18g
        "8", // Q18h
        "9"  // Q18i
    ];

    var validOrder = false;

    while (!validOrder) {

        // Fisher-Yates shuffle
        for (var i = order.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));

            var temp = order[i];
            order[i] = order[j];
            order[j] = temp;
        }

        // Codes 3 and 4 represent Q18c and Q18d
        var positionC = order.indexOf("3");
        var positionD = order.indexOf("4");

        validOrder = Math.abs(positionC - positionD) > 1;
    }

    f("Q18_POS1").set(order[0]);
    f("Q18_POS2").set(order[1]);
    f("Q18_POS3").set(order[2]);
    f("Q18_POS4").set(order[3]);
    f("Q18_POS5").set(order[4]);
    f("Q18_POS6").set(order[5]);
    f("Q18_POS7").set(order[6]);
    f("Q18_POS8").set(order[7]);
    f("Q18_POS9").set(order[8]);
}

