/*****
 *API DOC:
 https://developer.telesign.com/enterprise/reference/sendsmsverifycode

 ****/

//**Project specific settings**///
const PhoneNumber=f('MobileNumber')
const codeLength=6
const MAX_TELESIGN_TRY =3;
const Max_LOCAL_TRY =5;
f('MAX_LOCAL_TRY').set(Max_LOCAL_TRY)
f('MAX_TELESIGN_TRY').set(MAX_TELESIGN_TRY)


const URL_VERIFY = "https://rest-ww.telesign.com/v1/verify/sms";
//const CUSTOMER_ID = "redacted";
//const API_KEY = "redacted";
const AUTHENTICATION_BASE64 = "redacted";
const headers = {
  "accept": "application/json",
  "Content-Type": "application/x-www-form-urlencoded",
  "authorization": "redacted" + AUTHENTICATION_BASE64
};
let SenderId = "SRC";
let code="";
let message = "Your verification code is $$CODE$$."; //code case sensitive

if (Number(f('TELESIGN_API_TRYCOUNT').get() || 0) < MAX_TELESIGN_TRY )
{

  let tmp_TELESIGN_API_TRYCOUNT = Number(f('TELESIGN_API_TRYCOUNT').get() || 0)
  for (let i = 0; i < codeLength; i++) {
    code += Math.floor(Math.random() * 10).toString(); // 0–9
  }
  f('OTP_sent_save').set(code)

  const data = {
    "is_primary": 'true',
    "phone_number": '61' + PhoneNumber,
    "verify_code": code,
    "template": message
  }
  if( (!IsInProductionMode() || IsInRdgMode()))
  {

    //This is mock data for testing
  var response= JSON.stringify({
  "reference_id": "0123456789ABCDEF0123456789ABCDEF",
  "sub_resource": "sms",
  "errors": [],
  "status": {
    "updated_on": "2020-08-27T17:28:49.559307Z",
    "code": 290,
    "description": "Message in progress"
  },
  "verify": {
    "code_state": "UNKNOWN",
    "code_entered": ""
  }
})
  var jsonresult = JSON.parse(response)
  var statusresult=JSON.stringify(jsonresult['status'])

  Response.Write("For debugging - OTP_sent_save="+f('OTP_sent_save')+"</br>")

  } 
else
{
  var response = Http.Post(URL_VERIFY, data, headers);
  var jsonresult = JSON.parse(response)
  var statusresult=JSON.stringify(jsonresult['status'])

}

  f('verify_returned_status').set(JSON.parse(statusresult)['code'])
  f('TELESIGN_API_TRYCOUNT').set(tmp_TELESIGN_API_TRYCOUNT + 1)
  f('TELESIGN_response').set(response)
}

