SetRespondentValue('n_sections',f('n_sections'));

//update status and extended status
//SetStatus('complete');
//SetExtendedStatus('32'); //Early complete - main
//SetRespondentValue('extended_status','32');

//[WG] added on 22nd-MAy-2026
//AddRespondentToCati('32') //[WG] update cati side extended status and history

// INCENTIVE AWARD

var n_sections = Number(f('n_sections').get()) || 0;

// If the panellist completed the survey and they are not dummy
if (( GetExtendedStatus() == 13 || n_sections > 0 ) && f('dummy_sample').get() == 'N') {    
    // Add credit to the panellist for compeletes
    // By setting PanelistId to out-of-range (-1), we award credit to the CURRENT panelist
    SetPanelistCredit(Number(GetPoints()), PointsLabel(), -1, f('recordid').get());

    // If the status is currently null, we need to set the status to avoid pending incentive
    if (!GetStatus()) {
      SetStatus('Incomplete');
    }
}

//2=Main survey +omnibus1 completed
//f('n_sections').set('2')
SetRespondentValue('n_sections',f('n_sections'));

// [WG] [SUGGESTION] Danny - can we move this to 'SECTION - Omnibus 1' folder?
/* --------------------------

ADDITIONAL INCENTIVE AWARD

PLEASE READ - CONFIGURING THIS SCRIPT: 

Please carefully set the following values below before use:

- enabled
- index
- additional_incentive_amount
- min_n_sections

Then, please also review the receive_incentive condition below

*/

// enabled
var enabled = false // set to true to enable this additional incentive!

// index
var index = 1; // 1 means this is the first additional incentive, use 2 for the second and so on. Should match index in script title.

// amount
var additional_incentive_amount = 0; // Set to required amount in dollars

// min_n_sections
var min_n_sections = 2 // Set to the min value of n_sections required to qualify for this incentive

// receive_incentive condition
var is_not_dummy = f('dummy_sample').get() == 'N'
var exceeds_min_n_sections = f('n_sections').get() >= min_n_sections
var receive_incentive = is_not_dummy && exceeds_min_n_sections

// DO NOT EDIT BELOW THIS LINE ------
if (enabled && receive_incentive) {

    additional_points_label = AdditionalPointsLabel(String(additional_incentive_amount), 'section ' + String(index));
    sectionId = f('recordid').get() + "_" + String(index + 1);

    // Add credit to the panellist for compeletes
    // By setting PanelistId to out-of-range (-1), we award credit to the CURRENT panelist
    SetPanelistCredit(Number(additional_incentive_amount), additional_points_label, -1, sectionId);

    // If the status is currently null, we need to set the status to avoid pending incentive
    if (!GetStatus()) {
      SetStatus('Incomplete');
    }
}

//3=Main survey + omnibus1 + omnibus2 completed
//f('n_sections').set('3')
SetRespondentValue('n_sections',f('n_sections'));

//[WG] [DEAD CODE] the final STOP node will update them all
//SetExtendedStatus('13');  //[WG] is this to set CATI side? same as above this should be set on the stop node
//SetRespondentValue('extended_status','13'); //[WG] why do we need to set extended_status
//SetStatus('complete'); //[WG] LinA doesn't use redirect function, so this should be set on the stop node
//AddRespondentToCati('13')//From [SL] This creates a call entry with a defined status so CATI scheduling rules can act on it. In this case we're sending it through the scheduler as a complete so it's removed from dialling

